let harness: MongoReplicaSetHarness; const actor = new ObjectId(), other = new ObjectId();
const by = actor.toHexString(), byOther = other.toHexString();
const mutation = (expectedRevision: number) => ({ operationId: randomUUID(), expectedRevision });
const code = (expected: string) => (error: unknown) => error instanceof AdminImportError && error.code === expected;
const projects = () => getDb()!.collection<AdminImportDocument>('adminAlbumImports');
const stored = async (id: string) => (await projects().findOne({ _id: new ObjectId(id) }))!;

/** In-memory private storage; `afterPut` runs once a PUT landed, before the transfer records it. */
class Storage implements ImportObjectStorage {
    objects = new Map<string, { target: ImportObjectTarget; identity: ImportObjectIdentity }>(); failHead = false; afterPut?: () => Promise<void> | void;
    async head(target: ImportObjectTarget) { if (this.failHead) throw new Error('synthetic storage failure'); return this.objects.get(`${target.bucket}/${target.key}`)?.identity ?? null; }
    async put(target: ImportObjectTarget) { const identity = { etag: '"stage-etag"', versionId: 'stage-version' }; this.objects.set(`${target.bucket}/${target.key}`, { target, identity }); const hook = this.afterPut; this.afterPut = undefined; await hook?.(); return identity; }
    async copy(_source: ImportObjectTarget & ImportObjectIdentity, target: ImportObjectTarget) { const identity = { etag: '"canonical-etag"', versionId: 'canonical-version' }; this.objects.set(`${target.bucket}/${target.key}`, { target, identity }); return identity; }
    async delete(target: ImportObjectTarget & ImportObjectIdentity) { this.objects.delete(`${target.bucket}/${target.key}`); }
}
/** A short PCM WAV carrying ID3 text frames (frame ID, or `TXXX:<description>`, to text). */
const tagged = (filename: string, frames: Record<string, string>): Express.Multer.File => {
    const buffer = withId3TextFrames(createPcmWav(200), frames);
    return { fieldname: 'file', originalname: filename, mimetype: 'audio/wav', size: buffer.length, buffer, encoding: '7bit' } as Express.Multer.File;
};
/** An import of one file per relative path, with open sizes so any synthetic file fits its slot. */
async function project(paths: string[]) {
    const files = paths.map(relativePath => ({ slotId: randomUUID(), filename: relativePath.split('/').at(-1)!, relativePath, byteLength: null }));
    return createAdminImport(by, { operationId: randomUUID(), manifest: { rootLabel: paths.some(path => path.includes('/')) ? 'Synthetic Folder' : '', files } });
}
const slotOf = (item: AdminImportResponse['item'], index: number) => item.manifest.files[index].slotId;
const upload = (item: AdminImportResponse['item'], index: number, frames: Record<string, string>, storage: Storage, intent = mutation(1), actorId = by) =>
    uploadAdminImportAsset(actorId, item.id, slotOf(item, index), intent, tagged(item.manifest.files[index].filename, frames), storage);
const reconcile = (id: string, slotId: string, operationId: string, storage: Storage, actorId = byOther) => reconcileAdminImportAsset(actorId, id, slotId, { operationId }, storage);
const shared = { TALB: 'Synthetic Album', TYER: '2026', TPUB: 'Synthetic Label', TPE2: 'Synthetic Ensemble' };
const idle = { ran: false, written: [], skipped: [], album: false };
/** A preparing format-1 approval record, enough for the publication lock that guards the project's sources. */
const preparingPublication = () => ({ operationId: randomUUID(), actorId: by, state: 'preparing', issue: null, approvedRevision: 1, snapshot: {}, decisions: [], tracks: [], cover: null, bucket: 'synthetic-catalog',
    leaseOwner: null, leaseUntil: null, grantExpiresAt: new Date(Date.now() + 60_000), artistId: 'a'.repeat(24), newArtist: true, albumId: 'b'.repeat(24), newAlbum: true, albumRevision: null, coverId: null });
/** Arms a one-shot hook on the next read of an import project, which runs inside the next automation transaction. */
function onNextProjectRead(t: { mock: { method: typeof import('node:test').mock.method } }, work: () => Promise<unknown>) {
    let armed = false; const original = Collection.prototype.findOne;
    t.mock.method(Collection.prototype, 'findOne', async function (this: Collection, ...args: unknown[]) {
        if (armed && this.collectionName === 'adminAlbumImports') { armed = false; await work(); }
        return (original as (...values: unknown[]) => unknown).apply(this, args);
    });
    return () => { armed = true; };
}

